@import "tailwindcss";

/* Public Sans (variable, OFL), self-hosted. One file per subset serves every weight. */
@font-face {
  font-family: "Public Sans";
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
  src: url("/fonts/public-sans-latin-ext.woff2") format("woff2");
  unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF;
}
@font-face {
  font-family: "Public Sans";
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
  src: url("/fonts/public-sans-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

/* Direction A "Timetable" — proposal tokens (docs/iterations/04-web/D1/design-proposal.md). */
:root {
  --ground: #f3f5f7;      /* page */
  --surface: #ffffff;     /* cards, composer */
  --rail: #e9edf1;        /* conversation list, second neutral layer */
  --ink: #102030;         /* text, strong rules */
  --ink-2: #4a5866;       /* secondary text, 7.3:1 on surface */
  --hairline: #cbd3db;    /* 1px dividers (non-text) */
  --field: #8794a1;       /* input borders, 3.1:1 */
  --shell: #0e2f4a;       /* header band */
  --shell-ink: #ffffff;
  --shell-ink-2: #b7c9d9;
  --accent: #0b5d8f;      /* primary action, focus, links, selection; 7.1:1 with white */
  --accent-hover: #094b74;
  --accent-tint: #dde8f2; /* user bubble, selected row */
  --ok: #1a6b34;    --ok-bg: #e6f4ea;
  --warn: #7a4a00;  --warn-bg: #fff1d6;
  --danger: #b42318; --danger-bg: #fdecea;

  --ease-out: cubic-bezier(0.2, 0, 0, 1);
  --dur-1: 150ms; /* hover, colour */
  --dur-2: 200ms; /* enter, drawer */
}

@theme inline {
  --font-sans: "Public Sans", ui-sans-serif, system-ui, sans-serif;
  --color-background: var(--ground);
  --color-ground: var(--ground);
  --color-foreground: var(--ink);
  --color-ink: var(--ink);
  --color-muted: var(--ink-2);
  --color-ink-2: var(--ink-2);
  --color-border: var(--hairline);
  --color-hairline: var(--hairline);
  --color-field: var(--field);
  --color-card: var(--surface);
  --color-surface: var(--surface);
  --color-rail: var(--rail);
  --color-shell: var(--shell);
  --color-shell-ink: var(--shell-ink);
  --color-shell-ink-2: var(--shell-ink-2);
  --color-primary: var(--accent);
  --color-primary-fg: #ffffff;
  --color-accent: var(--accent);
  --color-accent-hover: var(--accent-hover);
  --color-accent-tint: var(--accent-tint);
  --color-ok: var(--ok);
  --color-ok-bg: var(--ok-bg);
  --color-warn: var(--warn);
  --color-warn-bg: var(--warn-bg);
  --color-danger: var(--danger);
  --color-danger-bg: var(--danger-bg);
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --text-xs: 0.75rem;   --text-xs--line-height: 1rem;
  --text-sm: 0.875rem;  --text-sm--line-height: 1.25rem;
  --text-base: 1rem;    --text-base--line-height: 1.5rem;
  --text-lg: 1.125rem;  --text-lg--line-height: 1.5rem;
  --text-xl: 1.375rem;  --text-xl--line-height: 1.75rem;
  --text-2xl: 1.75rem;  --text-2xl--line-height: 2.25rem;
}

html, body { height: 100%; }
body {
  background: var(--ground);
  color: var(--ink);
  font-family: var(--font-sans);
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}
::selection { background: var(--accent-tint); color: var(--ink); }
input, textarea { caret-color: var(--accent); }
input::placeholder { color: #5e6b78; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
* { scrollbar-color: var(--hairline) transparent; scrollbar-width: thin; }

/* Every figure is tabular so columns of km and $ line up. */
.figures { font-variant-numeric: tabular-nums; font-feature-settings: "tnum" 1; }

@keyframes enter { from { opacity: 0; transform: translateY(4px); } }
.enter { animation: enter var(--dur-2) var(--ease-out) both; }
@keyframes pulse-dot { 0%, 100% { opacity: 0.25; } 50% { opacity: 1; } }
.typing span { animation: pulse-dot 1.2s var(--ease-out) infinite; }
.typing span:nth-child(2) { animation-delay: 0.2s; }
.typing span:nth-child(3) { animation-delay: 0.4s; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0ms !important; animation-iteration-count: 1 !important; transition-duration: 0ms !important; }
}

